import uuid
from datetime import datetime
from decimal import Decimal
from typing import Annotated

from pydantic import BaseModel, ConfigDict, Field, StringConstraints, model_validator


class RawGiftIdea(BaseModel):
    """Raw gift idea generated by LLM inference before database persistence."""

    title: Annotated[str, StringConstraints(min_length=2, max_length=255, strip_whitespace=True)]
    description: Annotated[
        str, StringConstraints(min_length=10, max_length=2000, strip_whitespace=True)
    ]
    category: Annotated[str, StringConstraints(min_length=2, max_length=100, strip_whitespace=True)]
    personalization_reason: Annotated[
        str, StringConstraints(min_length=10, max_length=2000, strip_whitespace=True)
    ]
    estimated_budget: Decimal = Field(ge=Decimal("0.00"), decimal_places=2)
    presentation_idea: Annotated[
        str, StringConstraints(min_length=10, max_length=2000, strip_whitespace=True)
    ]


class RawGiftRecommendationOutput(BaseModel):
    """Schema expected from LLM structured JSON output. Must contain exactly 3 distinct recommendations."""

    recommendations: list[RawGiftIdea]

    @model_validator(mode="after")
    def validate_exactly_three_unique_ideas(self) -> "RawGiftRecommendationOutput":
        if len(self.recommendations) != 3:
            raise ValueError(
                f"Expected exactly 3 gift recommendations, received {len(self.recommendations)}"
            )

        titles = [r.title.strip().lower() for r in self.recommendations]
        if len(set(titles)) < 3:
            raise ValueError("All 3 gift recommendations must be meaningfully distinct")

        return self


class GiftRecommendationRead(BaseModel):
    """Public API schema for an individual gift recommendation."""

    id: uuid.UUID
    generation_id: uuid.UUID
    gift_project_id: uuid.UUID
    title: str
    description: str
    category: str
    personalization_reason: str
    estimated_budget: Decimal
    currency: str
    presentation_idea: str
    created_at: datetime

    model_config = ConfigDict(from_attributes=True)


class GiftRecommendationGenerationRead(BaseModel):
    """Public API schema for a gift recommendation generation batch."""

    id: uuid.UUID
    gift_project_id: uuid.UUID
    user_id: uuid.UUID
    provider: str
    model: str
    prompt_version: str
    status: str
    error_message: str | None = None
    created_at: datetime
    recommendations: list[GiftRecommendationRead] = Field(default_factory=list)

    model_config = ConfigDict(from_attributes=True)
